.sl-course-carousel.sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-course-carousel .sl-text-primary { color: var(--smartlearn-primary); }
.sl-course-carousel .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-course-carousel .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-course-carousel .sl-bg-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border); }
.sl-course-carousel .sl-border { border-color: var(--smartlearn-card-border); }
.sl-course-carousel .sl-card-radius { border-radius: var(--smartlearn-radius, 1rem); }
.sl-course-carousel h2, .sl-course-carousel h3 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-course-carousel .sl-media-fallback { background-color: var(--smartlearn-card-bg); }
.sl-course-carousel .sl-badge-subtle {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in oklab, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
    color: var(--smartlearn-primary);
    border: 1px solid var(--smartlearn-card-border);
    border: 1px solid color-mix(in oklab, var(--smartlearn-primary) 28%, var(--smartlearn-card-border));
}
.sl-course-carousel .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid var(--smartlearn-btn-bg);
    transition: background-color 0.2s ease, border-color 0.2s ease;
}
.sl-course-carousel .sl-btn-primary:hover,
.sl-course-carousel .sl-btn-primary:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    border-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}
.sl-course-carousel .sl-carousel-btn {
    width: 44px;
    height: 44px;
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text);
    border: 1px solid var(--smartlearn-card-border);
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease, opacity 0.2s ease;
}
.sl-course-carousel .sl-carousel-btn:hover:not(:disabled),
.sl-course-carousel .sl-carousel-btn:focus-visible:not(:disabled) {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-course-carousel .sl-carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }
[dir="rtl"] .sl-course-carousel .sl-carousel-btn i { transform: scaleX(-1); }
.sl-course-carousel .sl-slide-gradient {
    background: linear-gradient(to right, transparent, var(--smartlearn-card-bg));
}
[dir="rtl"] .sl-course-carousel .sl-slide-gradient {
    background: linear-gradient(to left, transparent, var(--smartlearn-card-bg));
}
.sl-course-carousel .sl-slider-track {
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
    touch-action: pan-y;
    cursor: grab;
}
.sl-course-carousel .sl-slider-track.is-dragging { cursor: grabbing; scroll-snap-type: none; }
.sl-course-carousel .sl-slider-track::-webkit-scrollbar { display: none; }
.sl-course-carousel .sl-slide { width: 90%; max-width: 900px; scroll-snap-align: start; }
.sl-course-carousel .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
.sl-course-carousel .sl-hover-zoom { transition: transform 0.6s ease; }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-course-carousel .sl-hover-card { transition: transform 0.3s ease, box-shadow 0.3s ease; }
    .sl-course-carousel .sl-hover-card:hover { transform: translateY(-5px); box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.12); }
    .sl-course-carousel .sl-hover-card:hover .sl-hover-zoom { transform: scale(1.05); }
}
@media (prefers-reduced-motion: reduce) {
    .sl-course-carousel .sl-hover-zoom, .sl-course-carousel .sl-hover-card, .sl-course-carousel .sl-btn-primary, .sl-course-carousel .sl-carousel-btn { transition: none; }
}
@media (min-width: 768px) {
    .sl-course-carousel .sl-slide { width: 85%; }
}
@media (min-width: 992px) {
    .sl-course-carousel { padding-top: 6rem !important; padding-bottom: 6rem !important; }
}

