(function() {
    const init = () => {
        document.querySelectorAll('.sl-course-carousel').forEach((section) => {
            if (section.dataset.slInit === '1') return;
            section.dataset.slInit = '1';

            const track = section.querySelector('.sl-slider-track');
            const prevBtn = section.querySelector('.sl-carousel-prev');
            const nextBtn = section.querySelector('.sl-carousel-next');
            if (!track || !prevBtn || !nextBtn) return;

            const getScrollAmount = () => {
                const slide = track.querySelector('.sl-slide');
                return slide ? slide.offsetWidth + 24 : 320;
            };

            const isRtl = () => getComputedStyle(track).direction === 'rtl';
            const getBehavior = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';

            const updateButtons = () => {
                const maxScroll = Math.max(0, track.scrollWidth - track.clientWidth);
                const current = Math.abs(track.scrollLeft);
                prevBtn.disabled = current <= 2;
                nextBtn.disabled = current >= maxScroll - 2;
            };

            const scrollStep = (forward) => {
                const dir = isRtl() ? -1 : 1;
                const delta = getScrollAmount() * (forward ? 1 : -1) * dir;
                track.scrollBy({ left: delta, behavior: getBehavior() });
            };

            nextBtn.addEventListener('click', () => scrollStep(true));
            prevBtn.addEventListener('click', () => scrollStep(false));
            track.addEventListener('scroll', updateButtons, { passive: true });
            window.addEventListener('resize', updateButtons, { passive: true });

            track.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowRight') {
                    e.preventDefault();
                    scrollStep(!isRtl());
                } else if (e.key === 'ArrowLeft') {
                    e.preventDefault();
                    scrollStep(isRtl());
                }
            });

            let isDown = false;
            let startX = 0;
            let startScroll = 0;

            track.addEventListener('pointerdown', (e) => {
                if (e.target.closest('a, button')) return;
                isDown = true;
                startX = e.clientX;
                startScroll = track.scrollLeft;
                track.classList.add('is-dragging');
            });
            window.addEventListener('pointermove', (e) => {
                if (!isDown) return;
                track.scrollLeft = startScroll - (e.clientX - startX);
            });
            const endDrag = () => {
                if (!isDown) return;
                isDown = false;
                track.classList.remove('is-dragging');
            };
            window.addEventListener('pointerup', endDrag);
            window.addEventListener('pointercancel', endDrag);

            updateButtons();
        });
    };
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
